CREATE TABLE tenants (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE organizations (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE properties (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), organization_id text NOT NULL, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta', UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,organization_id) REFERENCES organizations(tenant_id,id));
CREATE TABLE users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, developer boolean NOT NULL DEFAULT false);
CREATE TABLE memberships (tenant_id text NOT NULL REFERENCES tenants(id), user_id text NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('platform_admin','group_admin','hotel_manager','front_office','housekeeping','it')), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE property_grants (tenant_id text NOT NULL, user_id text NOT NULL, property_id text NOT NULL, PRIMARY KEY(tenant_id,user_id,property_id), FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE TABLE branding_profiles (tenant_id text PRIMARY KEY REFERENCES tenants(id), app_name text NOT NULL, primary_color text NOT NULL, logo text NOT NULL DEFAULT '', favicon text NOT NULL DEFAULT '/favicon.svg');
CREATE TABLE app_instances (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), hostname text UNIQUE NOT NULL);
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text NOT NULL, tenant_id text NOT NULL, csrf text NOT NULL, expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE connections (id text PRIMARY KEY, tenant_id text NOT NULL, property_id text NOT NULL UNIQUE, mode text NOT NULL CHECK(mode IN ('demo','real')), environment text NOT NULL, gateway text NOT NULL DEFAULT '', hotel_id text NOT NULL DEFAULT '', chain_code text NOT NULL DEFAULT '', enterprise_id text NOT NULL DEFAULT '', encrypted_secret text, status text NOT NULL DEFAULT 'not_connected', last_sync timestamptz, next_poll timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, checkpoint jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id), UNIQUE(tenant_id,id));
CREATE TABLE reservations (id text NOT NULL, tenant_id text NOT NULL, property_id text NOT NULL, confirmation text NOT NULL, guest_name text NOT NULL, arrival date NOT NULL, departure date NOT NULL, status text NOT NULL, room text, vip boolean NOT NULL DEFAULT false, source text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,property_id,id), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE INDEX reservation_search ON reservations(tenant_id,property_id,arrival,status);
CREATE TABLE guest_flags (tenant_id text NOT NULL, property_id text NOT NULL, reservation_id text NOT NULL, flag text NOT NULL, PRIMARY KEY(tenant_id,property_id,reservation_id,flag), FOREIGN KEY(tenant_id,property_id,reservation_id) REFERENCES reservations(tenant_id,property_id,id));
CREATE TABLE rooms (id text NOT NULL, tenant_id text NOT NULL, property_id text NOT NULL, status text NOT NULL, attention text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,property_id,id), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE TABLE tasks (id text PRIMARY KEY, tenant_id text NOT NULL, property_id text NOT NULL, title text NOT NULL, priority text NOT NULL CHECK(priority IN ('high','normal','low')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','acknowledged','done')), assignee text, updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id), FOREIGN KEY(tenant_id,assignee,property_id) REFERENCES property_grants(tenant_id,user_id,property_id));
CREATE TABLE integration_logs (id text PRIMARY KEY, tenant_id text NOT NULL, property_id text NOT NULL, operation text NOT NULL, status integer, latency integer NOT NULL, classification text NOT NULL, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE TABLE retry_jobs (id text PRIMARY KEY, tenant_id text NOT NULL, property_id text NOT NULL, operation text NOT NULL CHECK(operation='reservation_poll'), idempotency_key text NOT NULL, state text NOT NULL CHECK(state IN ('queued','running','done','dead')), attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, next_at timestamptz NOT NULL DEFAULT now(), last_error text, lease_until timestamptz, UNIQUE(tenant_id,property_id,idempotency_key), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE UNIQUE INDEX one_active_poll ON retry_jobs(tenant_id,property_id) WHERE state IN ('queued','running');
CREATE TABLE audit_logs (id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), property_id text, actor text NOT NULL, action text NOT NULL, target text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE TABLE integration_events (tenant_id text NOT NULL, property_id text NOT NULL, source_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,property_id,source_id), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE TABLE change_events (seq bigserial PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants(id), property_id text, topic text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,property_id) REFERENCES properties(tenant_id,id));
CREATE INDEX change_event_scope ON change_events(tenant_id,seq);
